CREATE TABLE IF NOT EXISTS roles (id INT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE);
INSERT IGNORE INTO roles VALUES (1,'Administrator'),(2,'Publisher');
CREATE TABLE IF NOT EXISTS permissions (id INT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
INSERT IGNORE INTO permissions VALUES (1,'announcements.manage'),(2,'users.manage'),(3,'wordpress.manage');
CREATE TABLE IF NOT EXISTS role_permissions (role_id INT NOT NULL, permission_id INT NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
INSERT IGNORE INTO role_permissions VALUES (1,1),(1,2),(1,3),(2,1);
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(190) NOT NULL,google_id VARCHAR(255) NULL UNIQUE,role_id INT NOT NULL DEFAULT 2,is_active BOOLEAN NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS login_sessions (id CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,device VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_seen DATETIME NOT NULL,expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS remembered_devices (selector CHAR(32) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,device VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS application_settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NULL);
CREATE TABLE IF NOT EXISTS wordpress_connections (id INT PRIMARY KEY,website_url VARCHAR(500) NOT NULL,rest_url VARCHAR(500) NOT NULL,username VARCHAR(190) NOT NULL,password_encrypted TEXT NOT NULL,connection_status VARCHAR(40) NOT NULL DEFAULT 'Untested',tested_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS category_mappings (module VARCHAR(40) PRIMARY KEY,category_name VARCHAR(100) NOT NULL,category_id BIGINT NULL);
INSERT IGNORE INTO category_mappings VALUES ('partial','POWER_ADVISORY',NULL),('scheduled','INTERRUPTIONS',NULL);
CREATE TABLE IF NOT EXISTS announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type ENUM('partial','scheduled') NOT NULL,title VARCHAR(255) NOT NULL,body MEDIUMTEXT NULL,image_path VARCHAR(100) NULL,image_mime VARCHAR(40) NULL,interruption_date DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS publishing_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,announcement_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL,wordpress_post_id BIGINT NULL,message VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(announcement_id) REFERENCES announcements(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
